let analysisCache=null,importQuality=null,previousReport=null;const analyst=new ClubPulseAnalyst();const analysis=()=>{if(!analysisCache){analysisCache=analyzeDataset(rows,{quality:importQuality});rows=analysisCache.rows}return analysisCache};

const deviceStorage={getItem:key=>localStorage.getItem(key),setItem:(key,value)=>localStorage.setItem(key,value)};const savedMeetings=loadEntries(deviceStorage);let userDrafts=savedMeetings.records;let rows=validEntries(userDrafts),isDemo=false,filter='all',dataSource='',updatedAt=null;const markUpdated=source=>{dataSource=source;updatedAt=new Date()};let reportCache=null;analysisCache=null;const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const num=n=>n==null?'Not provided':Number(n).toLocaleString('en-US',{maximumFractionDigits:1});const date=s=>new Date(s+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'});const report=()=>reportCache??=(modelReport(rows));const selected=()=>filter==='all'?sorted(rows):sorted(rows).slice(-Number(filter));
const workspaces=createWorkspaces(demoData);
function activateWorkspace(mode){const next=workspaces.switchTo(mode,{rows,importQuality,previousReport,analysisCache,reportCache,filter,dataSource,updatedAt});({rows,importQuality,previousReport,analysisCache,reportCache,filter,dataSource,updatedAt}=next);isDemo=mode==='demo'}
function workspaceLinks(){document.querySelectorAll('a[href^="#demo/"]').forEach(a=>a.href='#'+a.getAttribute('href').slice(6));document.querySelectorAll('nav a').forEach(a=>{if(a.dataset.page)a.href='#'+a.dataset.page});if(!isDemo)return;document.querySelectorAll('a[href^="#"]').forEach(a=>{const view=a.getAttribute('href').slice(1);if(['overview','insights','predict','retention','method'].includes(view))a.href='#demo/'+view;else if(view==='data')a.href='#import'});}
function heading(title,sub,action=''){return`<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}function notice(){return isDemo?'<div class="notice"><span>Explore a sample Sports Analytics club. All meetings and members are fictional.</span><a href="#data">Use your own data ↗</a></div>':'<div class="notice"><span>Your data is saved on this device. Export a backup from More.</span><a href="#data">Manage data ↗</a></div>'}function metric(label,value,note,icon){return`<div class="metric"><div class="metric-label">${label}<span class="metric-icon" aria-hidden="true">${icon}</span></div><div class="metric-value">${value}</div><div class="metric-note">${note}</div></div>`}function bars(data){const max=Math.max(...data.map(r=>r.avg),1);return data.map(r=>`<div class="bar-row"><div class="bar-meta"><span>${esc(r.name)} <small>· ${r.n} meetings</small></span><strong>${num(r.avg)}</strong></div><p class="footnote">${r.n<3?'Limited evidence: fewer than 3 meetings.':'Descriptive evidence: repeated examples, not proof of cause.'} ${num(r.avg-mean(rows.map(x=>x.attendance)))} attendees vs overall average.</p><div class="bar-track"><div class="bar-fill" style="width:${r.avg/max*100}%"></div></div></div>`).join('')||'<p class="empty">Add Meeting Type or Promotion Channels to compare groups. <a href="#sheets">View template →</a></p>'}
function chart(data){if(!data.length)return'<div class="empty">No meetings to chart yet.</div>';const w=650,h=235,l=35,r=15,t=15,b=32,max=Math.max(10,Math.ceil(Math.max(...data.map(r=>r.attendance))/10)*10);const point=(v,i)=>[l+(data.length===1?.5:i/(data.length-1))*(w-l-r),h-b-v/max*(h-b-t)];const points=data.map((d,i)=>point(d.attendance,i));const path=points.map(p=>p.join(',')).join(' '),rolling=data.map((d,i)=>point(mean(data.slice(Math.max(0,i-4),i+1).map(x=>x.attendance)),i).join(',')).join(' ');return`<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Attendance across ${data.length} meetings, from ${date(data[0].date)} to ${date(data.at(-1).date)}"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="var(--color-brand)" stop-opacity=".08"/><stop offset="1" stop-color="#97bf7c" stop-opacity=".01"/></linearGradient></defs>${[0,1,2,3,4].map(i=>{const y=h-b-i/4*(h-b-t);return`<line x1="${l}" x2="${w-r}" y1="${y}" y2="${y}" stroke="var(--color-border)" stroke-dasharray="3 4"/><text x="${l-10}" y="${y+4}" text-anchor="end">${Math.round(max*i/4)}</text>`}).join('')}<polygon points="${points[0][0]},${h-b} ${path} ${points.at(-1)[0]},${h-b}" fill="url(#chart-fill)"/><polyline points="${path}" fill="none" stroke="var(--color-brand)" stroke-width="2.5" stroke-linejoin="round"/><polyline points="${rolling}" fill="none" stroke="var(--color-chart-secondary)" stroke-width="2" stroke-dasharray="5 4"/>${points.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="3" fill="#fff" stroke="#34664c" stroke-width="1.8"><title>${esc(data[i].name)} · ${date(data[i].date)}: ${data[i].attendance} attendees</title></circle>`).join('')}${[...new Set([0,Math.floor((data.length-1)/3),Math.floor(2*(data.length-1)/3),data.length-1])].map(i=>`<text x="${points[i][0]}" y="${h-5}" text-anchor="${i===0?'start':i===data.length-1?'end':'middle'}">${date(data[i].date)}</text>`).join('')}</svg>`}
function recommendations(){const ts=groups(rows,'type').filter(g=>g.n>=3),ps=groups(rows,'promotion').filter(g=>g.n>=3),ret=retention(rows);const result=[];if(ts.length>1){const best=ts[0],worst=ts.at(-1);result.push({title:`Make room for ${best.name.toLowerCase()} meetings`,body:`${best.name} meetings averaged ${num(best.avg)} attendees across ${best.n} meetings, compared with ${num(worst.avg)} across ${worst.n} ${worst.name.toLowerCase()} meetings.`,action:`Try a ${best.name.toLowerCase()} at your next meeting and compare the turnout.`,evidence:'Historical association · Meeting topic, timing, and promotion may also explain the difference.'})}if(ps.length>1){const best=ps[0];result.push({title:'Give your promotion a clear plan',body:`${best.name} had the highest average turnout (${num(best.avg)}) among promotion methods with at least three meetings.`,action:`Try ${best.name.toLowerCase()} while keeping the meeting format similar. Record your reach before the meeting.`,evidence:`Based on ${best.n} meetings · These comparisons do not isolate the effect of promotion.`})}if(ret?.eligible){result.push({title:'Make the second meeting count',body:`${ret.returned} of ${ret.eligible} eligible newcomers returned within their next three meetings (${num(ret.rate*100)}%).`,action:ret.rate<.65?'Try a short welcome activity that helps new members meet someone they can return with.':'Keep a familiar activity in the next meeting so returning members know what to look forward to.',evidence:'Only newcomers with three follow-up meetings are included. Suggestions are experiments, not guaranteed improvements.'})}if(!result.length)result.push({title:'Build a useful starting point',body:'Add several meetings with different formats and promotion methods to reveal patterns.',action:'Track attendance consistently and include anonymous member IDs to understand who comes back.',evidence:'No reliable comparisons yet.'});return result}
function meetingTable(data,full=false){return`<div class="table-wrap"><table><thead><tr><th>Meeting</th><th>Date</th><th>Type</th>${full?'<th>Time</th><th>Promotion</th><th>Reach</th><th>Signups</th>':''}<th>Attendees</th>${full?'<th>Member IDs</th><th>Action</th>':''}</tr></thead><tbody>${data.map(r=>`<tr><td>${esc(r.name)}</td><td>${date(r.date)}${full?', '+r.date.slice(0,4):''}</td><td><span class="type-tag">${esc(r.type??'Not provided')}</span></td>${full?`<td>${esc(r.time??'Not provided')}</td><td>${esc(r.promotion??'Not provided')}</td><td>${num(r.reach)}</td><td>${num(r.signups)}</td>`:''}<td><strong>${r.attendance}</strong></td>${full?`<td>${r.members===null?'Not provided':r.members.length+' recorded'}</td><td><button class="text-link danger remove-row" data-id="${esc(r.id)}" aria-label="Remove ${esc(r.name)}">Remove</button></td>`:''}</tr>`).join('')||`<tr><td colspan="10">No meetings yet. Import a CSV or add your first meeting.</td></tr>`}</tbody></table></div>`}
function render(){$('#page').classList.remove('import-ready','demo-narrative','full-demo');document.querySelector('.workspace-more').open=false;const route=workspaceRoute(location.hash);if(['#demo/trend','#demo/full'].includes(location.hash))history.replaceState(null,'','#demo/overview');activateWorkspace(route.mode);if(rows.length)analysis();let page=route.page;if(isDemo&&!['demo','overview','insights','predict','retention','method'].includes(page))page='overview';if(!isDemo&&userDrafts.length!==validEntries(userDrafts).length&&['overview','insights','predict','retention'].includes(page)){page='data';history.replaceState(null,'','#data')}else if(!rows.length&&['overview','insights','predict','retention'].includes(page))page='import';document.body.classList.toggle('home-page',page==='home');const active=page==='import'?'data':['retention','insights'].includes(page)?'overview':page;document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.page===active);if(a.dataset.page===active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#breadcrumb').textContent={demo:'Demo workspace',sheets:'Google Sheets',home:'Home',import:'Import data',overview:'Insights',insights:'More insights',predict:'Next Meeting',retention:'Returning members',data:'Your data',method:'How it works'}[page]||'Your data';$('#dataset-pill').textContent=isDemo?'DEMO WORKSPACE':rows.length?rows.length+' meeting'+(rows.length===1?'':'s'):'Start here';$('#export-top').hidden=!rows.length;$('#workspace-type').textContent=isDemo?'Fictional sample data':'Your club';$('#club-name').textContent=isDemo?'Sports Analytics':'ClubPulse';({demo:demoPage,home:homePage,sheets:sheetsPage,import:importPage,overview,insights:insightsPage,predict:predictPage,retention:retentionPage,data:dataPage,method:methodPage}[page]||homePage)();bindCommon();const root=$('#page');root.dataset.view=page;document.body.classList.toggle('demo-mode',isDemo);document.body.classList.toggle('demo-entry-page',isDemo&&page==='demo');document.querySelector('#demo-context')?.remove();if(isDemo&&page!=='demo'){document.querySelector('.sidebar').insertAdjacentHTML('afterend',demoContextHTML());if(page==='predict')root.insertAdjacentHTML('beforeend',demoConversionHTML())}if(rows.length&&!['home','demo','import','sheets','data'].includes(page))root.insertAdjacentHTML('afterbegin',`<p class="source-meta">${rows.length} meeting${rows.length===1?'':'s'} · ${esc(dataSource||'Current workspace')} · Last updated: ${updatedAt?esc(updatedAt.toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})):'this session'}</p>`);document.querySelectorAll('form [name=reach],form [name=name],form [name=signups]').forEach(e=>e.required=false);document.querySelectorAll('form:not(#predict-form) select').forEach(e=>{if(!e.querySelector('option[value=""]')){e.insertAdjacentHTML('afterbegin','<option value="">Not provided</option>');e.value=''}});improveNavigation({page,rows,isDemo,outputs:analysisCache?.outputs,ready:rows.length?report().ready:false,escape:esc});workspaceLinks();if(isDemo&&page==='overview'){root.querySelector('.page-heading').insertAdjacentHTML('afterend','<p class="demo-analysis-intro">We’re using this club’s meeting history to understand what changed and what to try next.</p>');const planner=document.createElement('section');planner.className='demo-planner';planner.dataset.view='predict';root.querySelector('.demo-conversion').before(planner);predictPage(planner);planner.querySelector('h1').outerHTML='<h2>05 · Plan the next meeting</h2>';calmView({page:'predict',root:planner,rows});root.querySelector('.ask-disclosure').open=true;workspaceLinks();root.querySelector('[data-plan-type]')?.addEventListener('click',e=>{e.preventDefault();const select=planner.querySelector('[name=type]');select.value=e.currentTarget.dataset.planType;planner.querySelector('form').requestSubmit();planner.tabIndex=-1;planner.focus({preventScroll:true});planner.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});});}root.querySelector('[data-plan-type]')?.addEventListener('click',e=>{if(!isDemo)pendingRecommendation={mode:'user',type:e.currentTarget.dataset.planType}});if(page==='predict'){const section=$('#page > section.card');if(section){const details=document.createElement('details');details.className='card section-gap';details.innerHTML='<summary>How reliable is this prediction?</summary>'+section.innerHTML;section.replaceWith(details)}}}
function bindCommon(){document.querySelectorAll('.add-event').forEach(b=>b.onclick=()=>{if(isDemo)return;$('#event-form').reset();$('#event-error').textContent='';$('#event-form [name=date]').value=new Date().toISOString().slice(0,10);$('#event-dialog').showModal()})}function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500)}function download(name,text,mime='text/csv'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:mime+';charset=utf-8'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}const modalForm=$('#event-form');const modalGrid=modalForm.querySelector('.form-grid');modalGrid.nextElementSibling.remove();modalGrid.outerHTML=meetingFields();bindCountWarning(modalForm);refineEntry(modalForm);$('#export-top').onclick=()=>download('clubpulse-meetings.csv',toCSV(rows));$('#close-dialog').onclick=$('#cancel-dialog').onclick=()=>$('#event-dialog').close();$('#event-form').onsubmit=e=>{e.preventDefault();if(isDemo)return;try{const r=validateRow(formRecord(e.target));r.id=crypto.randomUUID();rows.push(r);userDrafts=rows.map(x=>({...x}));saveEntries(deviceStorage,userDrafts);markUpdated(isDemo?'Demo dataset (edited)':'Manual entry');importQuality=null;reportCache=null;analysisCache=null;$('#event-dialog').close();render();toast('Meeting added. Your insights have been updated.')}catch(err){$('#event-error').textContent=err.message}};window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0});const h=document.querySelector('#page h1');if(h){h.tabIndex=-1;h.focus({preventScroll:true})}});
function insightsPage(){const recs=recommendations();$('#page').innerHTML=heading('Find your next good idea.','Explore the patterns behind participation.')+notice()+`<div class="grid-two"><section class="card"><h2>Meeting formats</h2><p>Average attendees per meeting</p>${bars(groups(rows,'type'))}</section><section class="card"><h2>Promotion methods</h2><p>Average attendees per meeting</p>${bars(groups(rows,'promotion'))}</section></div><section class="card"><h2>What to try next</h2><p>Suggestions grounded in your meetings, with evidence you can inspect.</p><div class="insight-list">${recs.map((r,i)=>`<article class="insight"><span class="insight-number">0${i+1}</span><div><h3>${esc(r.title)}</h3><p>${esc(r.body)}</p><p><strong>Next experiment:</strong> ${esc(r.action)}</p><p class="footnote">${esc(r.evidence)}</p></div></article>`).join('')}</div></section><section class="card section-gap"><h2>When people show up</h2><p>Average attendance by meeting time</p>${bars(groups(rows,'time'))}<p class="footnote">Groups may differ in topic, semester timing, and promotion. A higher average does not prove that changing one factor will improve turnout.</p></section>`}
function predictPage(target=$('#page')){const m=report();const opts=k=>[...new Set(rows.map(r=>r[k]).filter(Boolean))].sort().map(x=>`<option>${esc(x)}</option>`).join('')||'<option value="">Not provided</option>';target.innerHTML=heading('Plan your next meeting','Use your club’s history to estimate turnout and choose what to try.')+notice()+`<div class="grid-two"><section class="card"><h2>The next meeting</h2><p>Use the details you know before the event.</p><form id="predict-form"><div class="form-grid">${planExtraFields()}<label>Meeting type<select name="type">${opts('type')}</select></label><label>Meeting time<select name="time">${opts('time')}</select></label><label>Expected reach before meeting<input name="reach" type="number" min="0" max="10000000" step="1" required value="300"></label></div>${promotionFields()}<button class="button primary" ${m.ready?'':'disabled'}>Estimate attendance ↗</button></form><div class="support-line"><span>ⓘ</span><span>Reach is a planning assumption. Final post-event reach and new signups are excluded from the model.</span></div></section><section class="card recommend-card prediction-result" id="prediction-output" aria-live="polite"></section></div><section class="card"><div class="section-heading"><div><h2>Trust the evidence, not just the number.</h2><p>Ridge regression is checked against a five-meeting rolling average.</p></div><a href="#method">View method ↗</a></div>${m.ready?`<div class="model-stats"><div class="model-stat">ML average error<strong>${num(m.mae)}</strong>attendees per test meeting</div><div class="model-stat">Rolling-average error<strong>${num(m.baselineMAE)}</strong>attendees per test meeting</div><div class="model-stat">Time-ordered test meetings<strong>${m.testCount}</strong>trained only on earlier dates</div></div><p class="footnote">Using ${m.useML?'ridge regression because it had lower historical error':'the recent average because it matched or outperformed the model'}. Model selection and error estimates use this small backtest; future performance may differ.${isDemo?' These results describe fictional sample data, not real-world accuracy.':''}</p>`:'<p>At least 12 meetings and four eligible time-ordered test cases are needed. Until then, the overview and historical comparisons remain available.</p>'}</section>`;const run=()=>{const output=$('#prediction-output');if(!m.ready){output.innerHTML='<div class="eyebrow">MORE HISTORY NEEDED</div><h2>Build your baseline.</h2><p>Add at least 12 meetings on different dates to start comparing predictions with actual results.</p><a class="button lime" href="#data">Add club data ↗</a>';return}const values=normalizePlan(formRecord($('#predict-form')));$('#predict-form').parentElement.querySelector('h2').textContent=values.type?'Your plan: '+values.type:'Plan your next meeting';const p=predict(m,values),explanation=forecastAttendance(rows,{event:values});output.innerHTML=`<p class="eyebrow">If you choose this plan</p><h2>Expected turnout</h2><div class="prediction-number">${p.estimate}</div><div class="prediction-range">attendees · planning range ${p.low}–${p.high}</div><p>${p.method==='Ridge regression'?'Learned from meeting format, time, promotion, and pre-meeting reach in your dataset.':'Your recent five meetings provide a stronger historical baseline than the trained model. Changing these inputs will not change this baseline.'}</p><h3>Why</h3>${planningEvidence(rows,values).map(x=>`<p><strong>${esc(x.label)}</strong><br>${esc(x.text)}</p>`).join('')}<p><strong>${esc(p.confidence.level)} confidence</strong> · ${esc(p.confidence.reason)} Typical historical error: ${num(m.typicalError)} attendees across ${m.testCount} tests.</p><p class="footnote">Meeting name and date are planning notes. The model uses recorded format, time, channel combinations and reach when they improve historical predictions.</p><details><summary>How this estimate works</summary><p>${esc(p.method)} · ${m.testCount} time-ordered tests.</p><p>Planning range uses the 80th percentile of observed absolute backtest errors. It is not a calibrated confidence interval.</p>${p.warnings.map(w=>`<p>${esc(w)}</p>`).join('')}<p>Typical backtest error: ${num(m.typicalError)} attendees.</p>${explanation.factors.map(f=>`<p>${esc(f.field)}: ${num(f.difference)} attendee model difference relative to the typical recorded value, holding other inputs typical. This is not a causal effect.</p>`).join('')}</details>`};$('#predict-form').onsubmit=e=>{e.preventDefault();run()};const typical=forecastAttendance(rows).typicalSetup;if(typical){for(const k of ['type','time'])if(typical[k])$('#predict-form [name='+k+']').value=typical[k];const channels=(typical.promotion||'').replace('Announcements','Classroom Announcement').split(' + ');document.querySelectorAll('#predict-form [name=channels]').forEach(c=>c.checked=channels.some(x=>x.toLowerCase()===c.value.toLowerCase()))}const typeSelect=$('#predict-form [name=type]');const preset=applyRecommendationPreset({type:typeSelect.value},pendingRecommendation,isDemo?'demo':'user',[...typeSelect.options].map(o=>o.value));typeSelect.value=preset.type;pendingRecommendation=null;run()}
function retentionPage(){const r=retention(rows);$('#page').innerHTML=heading('Give people a reason to return.','Understand the journey from first visit to familiar face.')+notice()+(r?`<div class="metrics">${metric('Unique members',r.unique,'At least one recorded meeting','◎')}${metric('Returned at least once',r.repeat,'Any later recorded meeting','↻')}${metric('Three or more meetings',r.consistent,'Across the full dataset','♧')}${metric('Newcomer return rate',r.rate==null?'—':Math.round(r.rate*100)+'%',`${r.returned} of ${r.eligible} eligible newcomers`,'↗')}</div><section class="card"><div class="section-heading"><div><h2>Newcomer cohorts</h2><p>Did first-time attendees come back within their next three meetings?</p></div></div><div class="table-wrap"><table><thead><tr><th>First meeting</th><th>Date</th><th>New members</th><th>Returned in next 3</th><th>Return rate</th></tr></thead><tbody>${r.cohorts.map(c=>`<tr><td>${esc(c.name)}</td><td>${date(c.date)}</td><td>${c.n}</td><td>${c.complete?c.returned:'Awaiting follow-up'}</td><td ${c.complete?'class="cohort-cell"':''}>${c.complete?Math.round(c.returned/c.n*100)+'%':'—'}</td></tr>`).join('')}</tbody></table></div><p class="footnote">Recent newcomers without three subsequent meetings are excluded from the rate. Member IDs must be stable across meetings. Multiple events on the same date count as separate meetings.</p></section>`:`<section class="card empty"><h2>${rows.length?'Member IDs are needed to measure retention.':'Start with your first meeting.'}</h2><p>Attendance totals alone cannot tell us who came back. Include anonymous, consistent IDs for every attendee in every meeting.</p><a class="button primary" href="#data">Import member attendance ↗</a></section>`)}
function methodPage(){$('#page').innerHTML=heading('How ClubPulse works','From meeting history to your next decision.')+`<section class="card how-steps"><h2>ClubPulse calculates before it explains</h2><ol><li><strong>Add your history.</strong> Your file is checked in this browser.</li><li><strong>See what changed.</strong> ClubPulse calculates trends and comparisons.</li><li><strong>Ask why.</strong> A local rule-based analyst selects relevant tools and explains their results. No external AI is connected.</li><li><strong>Plan your next meeting.</strong> Try an idea and review its historical evidence.</li></ol></section>`+`<article class="card method-content"><section><h2>What the AI actually does</h2><p>ClubPulse fits a ridge regression model to your current meeting dataset. It learns numerical weights for meeting type, meeting time, promotion method, and log-transformed pre-meeting reach. Training and prediction happen directly in your browser. Ask ClubPulse uses a bounded local question router and deterministic analysis tools. No external LLM is configured. Answers are assembled from calculated evidence; no model invents results.</p></section><section><h2>A baseline has to earn its place</h2><p>With at least 12 meetings, we test up to the 10 most recent meetings using only meetings on earlier dates for training. Each training set needs at least eight meetings, and at least four test cases must be available. We compare mean absolute error—the average number of attendees missed—with a rolling average of the five most recent training meetings. Whichever has lower error produces the estimate. Ties use the simpler rolling average.</p><p>The ridge penalty is fixed at 5; the intercept is not penalized. Categories and numeric scaling are learned separately inside each training fold. Attendance and post-meeting signups are never inputs. We do not claim a validated accuracy percentage: the same small backtest selects the method and summarizes errors.</p></section><section><h2>The planning range</h2><p>The estimate is expanded by the 80th percentile of absolute errors from the selected method’s backtest. The lower bound cannot fall below zero. This is a rough planning aid, not an 80% confidence interval or a promise about future turnout.</p></section><section><h2>Retention with a fair follow-up window</h2><p>A newcomer is an ID appearing for the first time in the dataset. A returned newcomer attends at least one of the next three recorded meetings. Only newcomers with all three follow-up meetings available enter the denominator. Missing member IDs disable retention instead of guessing from attendance totals. These are observed newcomers in your records, who may have attended before those records began.</p></section><section><h2>Recommendations are testable ideas</h2><p>Format and promotion comparisons show averages and group sizes. Recommendations require at least three meetings in each compared group, but even then they are descriptive associations. A popular topic, exam week, or a special guest can change attendance. Suggestions are generated from transparent rules applied to these calculations; they are not independent causal findings.</p></section><section><h2>Your data stays with you</h2><p>Imported files and entered meetings are saved in this browser on this device. They are not sent to our server. Export your CSV for a backup or before clearing browser storage. Use anonymous member IDs instead of names or email addresses. The default demonstration is fictional and is never a claim of real club impact.</p></section></article>`}
function dataPage(){mountMeetingEditor($('#page'),{records:userDrafts,initialError:savedMeetings.error,save:records=>{userDrafts=records;return saveEntries(deviceStorage,records)},onChange:normalized=>{rows=normalized;markUpdated('On-site meeting history');importQuality=null;reportCache=null;analysisCache=null}})}
function qualityHTML(q){return `<div class="quality-summary"><h3>${q.usableRows} usable meetings</h3><p>${q.duplicateRows} duplicates · ${q.excludedRows.length} excluded rows · ${q.fieldIssues.length} optional-field issues</p><details><summary>Review data checks</summary>${q.warnings.map(w=>`<p>${esc(w)}</p>`).join('')}${q.excludedRows.map(r=>`<p>Row ${r.row}: ${esc(r.reason)}</p>`).join('')}${q.fieldIssues.map(r=>`<p>Row ${r.row}, ${esc(r.field)}: ${esc(r.reason)}</p>`).join('')}<p>${q.normalizations.length} category values standardized.</p></details></div>`}
function answerHTML(a){const priority=['Attendance comparison','Social reach changed','Returning-member participation','Recent meeting format','When promotion started'];const signals=[...a.signals].sort((x,y)=>(priority.includes(x.title)?priority.indexOf(x.title):99)-(priority.includes(y.title)?priority.indexOf(y.title):99));const signal=(s,i)=>`<article class="answer-signal"><strong>${i+1}. ${esc(s.title)}</strong><p>${esc(s.text)}</p></article>`;return `<div class="eyebrow">${esc(a.mode)}</div><h3>${esc(a.title)}</h3><p class="answer-summary">${esc(a.summary)}</p>${!a.signals.length&&a.caveats.length?`<p>${esc(a.caveats[0])}</p>`:''}<h3>Main signals</h3>${signals.slice(0,3).map(signal).join('')}${signals.length>3?`<details><summary>More supporting evidence (${signals.length-3})</summary>${signals.slice(3).map((s,i)=>signal(s,i+3)).join('')}</details>`:''}${a.recommendations.length?'<h3>What to try next</h3>':''}${a.recommendations.slice(0,1).map(r=>`<p><strong>${esc(r.title)}</strong><br>${esc(r.evidence)} ${esc(r.reason)}</p>`).join('')}${a.recommendations.length>1?`<details><summary>Other ideas to test</summary>${a.recommendations.slice(1).map(r=>`<p><strong>${esc(r.title)}</strong><br>${esc(r.evidence)} ${esc(r.reason)}</p>`).join('')}</details>`:''}<h3>Evidence strength</h3><p><strong>${esc(a.confidence.level)}</strong> · ${esc(a.confidence.reason)}</p><details><summary>Analysis used and limitations</summary><p>${a.trace.map(t=>esc(t.label)).join(' · ')}</p>${a.caveats.map(c=>`<p>${esc(c)}</p>`).join('')}<ol>${a.trace.map(t=>`<li>${esc(t.label)} · ${esc(t.status)} · ${t.sampleSize} meetings</li>`).join('')}</ol></details>`}
function overview(){const s=analysis(),o=s.outputs,a=o.calculate_attendance_metrics,t=o.calculate_attendance_trend,r=o.calculate_retention,p=o.compare_prediction_to_actual,rec=o.recommend_next_steps.recommendations[0];$('#page').innerHTML=heading('Your club, explained.','See what changed. Ask why. Choose what to try next.')+notice()+`<div class="metrics simple-metrics">${metric('Meetings',rows.length,'Included in this analysis','▤')}${metric('Average attendance',num(a.average),'About '+num(Math.round(a.average))+' people at a typical meeting. '+(t.available?'Recent average: '+num(t.current)+' attendees.':'Add six meetings to compare recent turnout.'),'◎')}${metric('Recent momentum',t.available?t.direction:'Building history',t.available?num(t.percentChange)+'% · last 3 vs previous 3':'Record six meetings to compare','↗')}</div><section class="card ask-card"><div class="eyebrow">ASK CLUBPULSE</div><h2>Ask ClubPulse</h2><p>Ask about attendance, promotion, returning members, or your next meeting.</p><form id="ask-form"><label class="sr-only" for="club-question">Your question</label><textarea id="club-question" rows="2" maxlength="600" required placeholder="Why has attendance changed recently?"></textarea><button class="button primary">Analyze my meetings →</button></form><div class="question-chips">${['Why is attendance falling?','What changed recently?','Which meeting types perform better?','Is promotion helping?','What should we try next?'].map(q=>`<button class="button small suggested-question" data-question="${esc(q)}">${esc(q)}</button>`).join('')}</div><p class="footnote">Calculated locally from your data. Rule-based analysis; no external chatbot.</p><div id="ask-answer" aria-live="polite"></div></section><section class="card section-gap"><h2>Attendance over time</h2><p class="footnote">Vertical: attendees · Horizontal: meeting date · Solid green: actual · Dashed gold: rolling five-meeting average</p>${chart(sorted(rows))}<p>Latest five-meeting average: <strong>${num(a.rollingAverage.at(-1)?.value)}</strong>. ${o.detect_attendance_anomalies.items.length} unusual meeting(s) flagged for review.</p></section><section class="card section-gap"><div class="eyebrow">MEETING PULSE</div><h2>${esc(p.meeting?.name??'Latest meeting')}</h2>${p.available?`<p><strong>${p.actual} attendees</strong>, compared with ${num(p.baseline)} for ${esc(p.baselineLabel.toLowerCase())}. Difference: ${num(p.difference)} attendees.</p><details><summary>What else changed?</summary>${p.signals.map(x=>`<p>${esc(x.name)}: ${num(x.actual)} vs ${num(x.baseline)} previously (${x.sampleSize} meetings).</p>`).join('')||'<p>Add optional promotion, reach, or member data to compare more signals.</p>'}<p class="footnote">Historical baseline, not a saved pre-meeting forecast. These associations do not establish causes.</p></details>`:'<p>Record another meeting on a later date to compare it with earlier attendance.</p>'}</section>${recommendationHTML(o,{demo:isDemo})}<details class="card section-gap"><summary>Club health & deeper insights</summary><div class="health-grid">${o.generate_club_health_summary.components.map(c=>`<article><h3>${esc(c.name)}</h3><strong>${esc(c.label)}</strong><p>${esc(c.definition)}</p></article>`).join('')}</div><div class="grid-two"><section><h3>Meeting formats</h3>${bars(groups(rows,'type'))}</section><section><h3>Promotion strategies</h3>${bars(groups(rows,'promotion'))}</section></div><p>Returning newcomers: ${r.available&&r.rate!=null?num(r.rate*100)+'% ('+r.returned+'/'+r.eligible+' eligible newcomers)':'Requires complete anonymous IDs and three follow-up meetings.'}</p><a class="text-link" href="#retention">Retention details →</a><p class="footnote">Historical patterns do not prove cause and effect. Category comparisons need repeated examples.</p></details><details class="card section-gap"><summary>Data quality & automatic analysis</summary>${coverageHTML(rows)}${qualityHTML(s.quality)}<ol>${s.steps.map(x=>`<li>${esc(x.label)} · ${esc(x.status)}</li>`).join('')}</ol></details><div class="entry-actions"><button class="button" id="health-report">Download health report</button><a class="button" href="#data">Manage my data</a></div><p id="report-status" aria-live="polite"></p>`;
let askRun=0;$('#ask-answer').addEventListener('clear-analysis',()=>{askRun++;$('#ask-form button').disabled=false});const ask=async question=>{const run=++askRun,questionRows=rows,questionQuality=importQuality;const output=$('#ask-answer');output.textContent='Checking data and calculating relevant evidence…';const button=$('#ask-form button');button.disabled=true;try{await new Promise(resolve=>requestAnimationFrame(resolve));const steps=[];const answer=await analyst.analyze(question,questionRows,{quality:questionQuality,onTool:async step=>{steps.push(step);if(output.isConnected&&run===askRun)output.innerHTML='<p><strong>Investigating your club…</strong></p><ul class="analysis-progress">'+steps.map(x=>'<li>✓ '+esc(x.label)+'</li>').join('')+'</ul>';await new Promise(resolve=>requestAnimationFrame(resolve))}});if(output.isConnected&&run===askRun)output.innerHTML=answerHTML(answer)}catch(e){if(output.isConnected&&run===askRun)output.textContent=e.message}finally{if(run===askRun)button.disabled=false}};$('#ask-form').onsubmit=e=>{e.preventDefault();ask($('#club-question').value)};document.querySelectorAll('.suggested-question').forEach(b=>b.onclick=()=>{$('#club-question').value=b.dataset.question;ask(b.dataset.question)});$('#health-report').onclick=()=>{const result=generateClubReport(rows,{quality:importQuality,previous:previousReport,demo:isDemo});download('clubpulse-health-report.md',result.text,'text/markdown');$('#report-status').textContent=previousReport?(result.changes.changed?'Updated report generated from changed data.':'Report generated; data is unchanged since your last report.'):'Health report generated from this dataset.';previousReport=result};}


function demoPage(){$('#page').innerHTML=demoIntroHTML({rows})}
function homePage(){$('#page').innerHTML=homeHTML(rows.length,isDemo)}
function sheetsPage(){$('#page').innerHTML=sheetsHTML();bindSharedUploader()}
function importPage(){$('#page').innerHTML=heading('Add your meeting history','Enter your meetings directly or upload an existing spreadsheet.')+'<section class="direct-entry-choice"><h2>Enter Data on ClubPulse</h2><p>Add your past meetings directly. No spreadsheet needed.</p><a class="button primary" href="#data">Start Entering Meetings →</a></section><section id="import-section" class="primary-import"><h2>Upload Spreadsheet</h2><p class="upload-choice-copy">Already track your club in Excel or CSV? Upload it here.</p>'+uploaderHTML('Upload Spreadsheet')+'</section><section class="template-helpers"><h2>Prefer a template?</h2><div class="template-options"><div><h3>Google Sheets</h3><p>An optional way to keep your history outside ClubPulse.</p><a href="#sheets">Use Google Sheets Template →</a></div><div><h3>Excel</h3><p>Prefer an offline spreadsheet?</p><a href="templates/clubpulse-template.xlsx" download>Download Excel Template →</a></div><div><h3>CSV</h3><p>Want a simple file?</p><a href="templates/clubpulse-template.csv" download>Download CSV Template →</a></div></div></section>'+(rows.length?'<p class="saved-workspace">Your '+rows.length+' meetings are saved on this device. <a href="#overview">Return to your insights →</a></p>':'');bindSharedUploader()}


document.querySelector('.skip').onclick=e=>{e.preventDefault();document.querySelector('#main').focus()};
render();
// Progressive enhancement for browsers with a page-scoped WebMCP registry.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tools=[{name:'read_club_summary',description:'Read attendance and retention statistics for the currently loaded club dataset.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:input=>{if(input&&Object.keys(input).length)throw Error('This tool takes no parameters.');const r=retention(rows);return{sampleData:isDemo,meetings:rows.length,averageAttendance:mean(rows.map(r=>r.attendance)),retentionRate:r?.rate??null,uniqueMembers:r?.unique??null}}},{name:'navigate_club_view',description:'Open an existing ClubPulse analysis view. This changes navigation only.',inputSchema:{type:'object',properties:{view:{type:'string',enum:['home','demo','sheets','import','overview','insights','predict','retention','data','method']}},required:['view'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||Object.keys(input).some(k=>k!=='view')||!['home','demo','sheets','import','overview','insights','predict','retention','data','method'].includes(input.view))throw Error('Choose a supported club view.');history.replaceState(null,'','#'+(isDemo&&['overview','insights','predict','retention','method'].includes(input.view)?'demo/':'')+input.view);render();return{view:input.view}}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}


function bindSharedUploader(){bindUploader($('#page'),{coverageHTML,qualityHTML,onImportSuccess:async(checked,file)=>{toast('Analyzing club history…');rows=checked.rows;userDrafts=rows.map(r=>({...r}));const saveError=saveEntries(deviceStorage,userDrafts);markUpdated(file.name.toLowerCase().endsWith('.xlsx')?'Excel upload':'CSV upload');importQuality=checked.quality;isDemo=false;filter='all';reportCache=null;analysisCache=null;location.hash='data';render();toast(saveError||'Meetings imported. Review and edit them before analysis.')}})}


const moreMenu=document.querySelector('.workspace-more');document.addEventListener('click',e=>{if(!moreMenu.contains(e.target))moreMenu.open=false});moreMenu.addEventListener('keydown',e=>{if(e.key==='Escape'){moreMenu.open=false;moreMenu.querySelector('summary').focus()}});
